"""NVIDIA Warp fused kernel (generated by :mod:`pylbm.codegen`, one thread per node)."""

from __future__ import annotations

from typing import Any

from ..codegen import load, spec_for
from ._fused import FusedSolver, cuda_ok

try:
    import warp as wp

    wp.config.quiet = True
    _HAVE = True
except Exception:  # pragma: no cover
    _HAVE = False

_INIT = False


def _init() -> None:
    global _INIT
    if not _INIT:
        wp.init()
        _INIT = True


class WarpFused(FusedSolver):
    """``@wp.kernel`` launched over (nz,) ny, nx; fp32, two buffers."""

    backend = "warp"
    variant = "fused"
    description = "NVIDIA Warp fused stream+collide+BC, pull, SoA, two buffers"

    @classmethod
    def available(cls) -> tuple[bool, str]:
        if not _HAVE:
            return False, "warp-lang not installed"
        return cuda_ok()

    def _compile(self) -> None:
        _init()
        p = self.problem
        pats = ("aa-odd", "aa-even") if self.aa else ("ab",)
        self.kernels = {pat: load(spec_for(p, self.storage, pat), "warp").lbm_kernel
                        for pat in pats}
        self.dim = tuple(reversed(p.shape))
        a = self.scalar_args()
        self.args = [int(v) for v in a[:4]] + [float(v) for v in a[4:]]
        self.device = wp.get_device("cuda:0")
        # launch on torch's current stream so ordering with torch ops is preserved
        import torch

        self.stream = wp.stream_from_torch(torch.cuda.current_stream())
        self._views: dict[int, Any] = {}

    def _view(self, t: Any) -> Any:
        key = t.data_ptr()
        if key not in self._views:
            self._views[key] = wp.from_torch(t)
        return self._views[key]

    def _launch(self, which: str, src: Any, dst: Any) -> None:
        wp.launch(self.kernels[which], dim=self.dim,
                  inputs=[self._view(src), self._view(dst), *self.args],
                  device=self.device, stream=self.stream)
